/**
 * Recognize a mini-app front-end from package.json dependency names.
 * Returns null, or { name, source, hashedAssets? }: `source` is the build
 * output folder (null when the framework has no fixed static output folder);
 * `hashedAssets` is where the tool puts content-hashed files by default.
 */

// Frameworks with their own build and no fixed static output folder. Checked
// before plain `vite`, which many of them also list.
const OWN_BUILD = [
  ['next', 'Next.js'],
  ['nuxt', 'Nuxt'],
  ['@sveltejs/kit', 'SvelteKit'],
  ['@react-router/dev', 'React Router'],
  ['@tanstack/react-start', 'TanStack Start'],
  ['@angular/core', 'Angular'],
  // list `vite` as a peer dependency
  ['@remix-run/dev', 'Remix'],
  ['@tanstack/solid-start', 'TanStack Start'],
  ['@solidjs/start', 'SolidStart'],
  ['@builder.io/qwik-city', 'QwikCity'],
  ['@analogjs/platform', 'Analog'],
  ['vike', 'Vike'],
  ['rwsdk', 'RedwoodSDK'],
];

// Static-output tools with a fixed default build folder: [dep, name, source, hashedAssets?].
const STATIC_OUTPUT = [
  ['react-scripts', 'Create React App', 'build'],
  ['vite', 'Vite', 'dist', '/assets/*'],
];

export function detectFrontend(pkg) {
  if (!pkg || typeof pkg !== 'object') return null;
  const deps = { ...pkg.dependencies, ...pkg.devDependencies };
  for (const [dep, name] of OWN_BUILD) {
    if (dep in deps) return { name, source: null };
  }
  for (const [dep, name, source, hashedAssets] of STATIC_OUTPUT) {
    if (dep in deps) return hashedAssets ? { name, source, hashedAssets } : { name, source };
  }
  return null;
}
